  1→//! Session ID generation and parsing.
  2→
  3→use chrono::{DateTime, Utc};
  4→use serde::{Deserialize, Serialize};
  5→use std::fmt;
  6→
  7→/// A unique session identifier.
  8→///
  9→/// Format: `sess_{timestamp_ms}_{random_hex}`
 10→#[derive(Debug, Clone, PartialEq, Eq, Hash)]
 11→pub struct SessionId {
 12→    timestamp: DateTime<Utc>,
 13→    random: [u8; 8],
 14→}
 15→
 16→impl SessionId {
 17→    /// Generate a new session ID.
 18→    pub fn new() -> Self {
 19→        let mut random = [0u8; 8];
 20→        getrandom::getrandom(&mut random).expect("Failed to generate random bytes");
 21→
 22→        // Truncate to milliseconds for consistent serialization
 23→        let now = Utc::now();
 24→        let timestamp = DateTime::from_timestamp_millis(now.timestamp_millis()).unwrap_or(now);
 25→
 26→        Self { timestamp, random }
 27→    }
 28→
 29→    /// Get the session timestamp.
 30→    pub fn timestamp(&self) -> DateTime<Utc> {
 31→        self.timestamp
 32→    }
 33→
 34→    /// Get the ID as a string.
 35→    pub fn as_str(&self) -> String {
 36→        self.to_string()
 37→    }
 38→
 39→    /// Parse a session ID from a string.
 40→    pub fn parse(s: &str) -> Option<Self> {
 41→        let s = s.strip_prefix("sess_")?;
 42→        let parts: Vec<&str> = s.split('_').collect();
 43→        if parts.len() != 2 {
 44→            return None;
 45→        }
 46→
 47→        let ts_millis: i64 = parts[0].parse().ok()?;
 48→        let timestamp = DateTime::from_timestamp_millis(ts_millis)?;
 49→        let random_hex = parts[1];
 50→        let random_bytes = hex::decode(random_hex).ok()?;
 51→        if random_bytes.len() != 8 {
 52→            return None;
 53→        }
 54→
 55→        let mut random = [0u8; 8];
 56→        random.copy_from_slice(&random_bytes);
 57→
 58→        Some(Self { timestamp, random })
 59→    }
 60→}
 61→
 62→impl Default for SessionId {
 63→    fn default() -> Self {
 64→        Self::new()
 65→    }
 66→}
 67→
 68→impl fmt::Display for SessionId {
 69→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 70→        write!(
 71→            f,
 72→            "sess_{}_{}",
 73→            self.timestamp.timestamp_millis(),
 74→            hex::encode(self.random)
 75→        )
 76→    }
 77→}
 78→
 79→// Custom serialization to store as string
 80→impl Serialize for SessionId {
 81→    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
 82→    where
 83→        S: serde::Serializer,
 84→    {
 85→        serializer.serialize_str(&self.to_string())
 86→    }
 87→}
 88→
 89→impl<'de> Deserialize<'de> for SessionId {
 90→    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
 91→    where
 92→        D: serde::Deserializer<'de>,
 93→    {
 94→        let s = String::deserialize(deserializer)?;
 95→        SessionId::parse(&s).ok_or_else(|| serde::de::Error::custom("Invalid session ID format"))
 96→    }
 97→}
